package com.financialfraudassistant.controller;
import com.financialfraudassistant.dto.BudgetRequest; import com.financialfraudassistant.model.*; import com.financialfraudassistant.repository.BudgetRepository; import com.financialfraudassistant.service.CurrentUserService; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/budgets") public class BudgetController { private final BudgetRepository repo; private final CurrentUserService users; public BudgetController(BudgetRepository r,CurrentUserService u){repo=r;users=u;} @GetMapping public List<Budget> list(Authentication a){return repo.findByUserIdOrderByCategory(users.requireUser(a).getId());} @PostMapping public Budget create(Authentication a,@Valid @RequestBody BudgetRequest r){User u=users.requireUser(a); return repo.save(new Budget(u,r.category().trim(),r.monthlyLimit()));} }
